CREATE TABLE WF360_DATAGRID (
  ID NUMBER(19) PRIMARY KEY, GRID_NAME VARCHAR2(120 CHAR) NOT NULL UNIQUE
);
CREATE TABLE WF360_DATAGRID_METADATA (
  ID NUMBER(19) PRIMARY KEY, METADATA_KEY VARCHAR2(120 CHAR) NOT NULL, METADATA_VALUE CLOB NOT NULL,
  DATAGRIDID NUMBER(19) NOT NULL, CONSTRAINT WF360_GRID_METADATA_FK FOREIGN KEY (DATAGRIDID) REFERENCES WF360_DATAGRID(ID)
);
CREATE TABLE WF360_DATAGRID_DATAMAPPING (
  ID NUMBER(19) PRIMARY KEY, DATAGRIDID NUMBER(19) NOT NULL, TABLE_NAME VARCHAR2(120 CHAR) NOT NULL,
  COLUMN_NAME VARCHAR2(120 CHAR) NOT NULL, COLUMN_ORDER NUMBER(5) NOT NULL, UIDISPLAY_NAME VARCHAR2(120 CHAR) NOT NULL,
  WIDTH VARCHAR2(30 CHAR), SORTABLE CHAR(1 CHAR) DEFAULT 'Y' NOT NULL, ISHYPERLINK CHAR(1 CHAR) DEFAULT 'N' NOT NULL,
  TYPE VARCHAR2(40 CHAR), SHOWFILTER CHAR(1 CHAR) DEFAULT 'N' NOT NULL, CRE_BY VARCHAR2(120 CHAR) NOT NULL,
  CRE_DATE TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, UPD_BY VARCHAR2(120 CHAR), UPD_DATE TIMESTAMP WITH TIME ZONE,
  CONSTRAINT WF360_GRID_MAPPING_FK FOREIGN KEY (DATAGRIDID) REFERENCES WF360_DATAGRID(ID)
);

