DECLARE v_form_id NUMBER; v_field_id NUMBER;
  PROCEDURE f(c VARCHAR2,n VARCHAR2,t VARCHAR2,m CHAR) IS BEGIN SELECT NVL(MAX(ID),0)+1 INTO v_field_id FROM WF_FORM_FIELDS_MASTER; INSERT INTO WF_FORM_FIELDS_MASTER(ID,FORM_ID,FIELD_CODE,FIELD_NAME,FIELD_TYPE,IS_MANDATORY,IS_ACTIVE,CRE_BY) VALUES(v_field_id,v_form_id,c,n,t,m,'Y','SYSTEM'); END;
BEGIN
  SELECT NVL(MAX(ID),0)+1 INTO v_form_id FROM WF_FORM_MASTER;
  INSERT INTO WF_FORM_MASTER(ID,FORM_CODE,FORM_NAME,IS_ACTIVE,CRE_BY) VALUES(v_form_id,'role_designation','Role & Designation','Y','SYSTEM');
  f('ROLE_NAME','Designation','TEXTBOX','Y'); f('ROLE_DESC','Description','TEXTBOX','N'); f('ROLE_LEVEL','Designation Level','DROPDOWN','Y'); f('IS_ACTIVE','Status','DROPDOWN','Y');
END;
/
INSERT INTO WF_STATIC_CONFIG (ID, CONF_CODE, CONF_CATEGORY, STATIC_JSON, IS_ACTIVE, CRE_BY)
SELECT NVL(MAX(ID),0)+1, 'EDIT_ROLE_DESIGNATION', 'UPDATE_DETAILS', '{"title":"Edit Role & Designation","description":"Update designation details.","formCode":"role_designation","saveButtonLabel":"Save Changes","columns":2}', 'Y', 'SYSTEM' FROM WF_STATIC_CONFIG;
